"use strict";

module.exports = function diagnosticsProbe() {
  const diagnostics = require("diagnostics_channel");
  const channel = diagnostics.channel("core-feature");
  const seen = [];
  function listener(message, name) {
    seen.push(name + ":" + message.value);
  }
  channel.subscribe(listener);
  const before = channel.hasSubscribers;
  channel.publish({ value: 1 });
  channel.unsubscribe(listener);
  const after = channel.hasSubscribers;
  return {
    ok:
      seen.join(",") === "core-feature:1" &&
      before === true &&
      after === false,
    summary: "diagnostics:" + seen.join(",") + ":" + before + ":" + after,
  };
};
